from pathlib import Path
from datetime import datetime,timezone
import json,os
pids=[1270424,1270633,1270767,1270910,1271056,1271168];rows={}
for pid in pids:
 base=Path('/proc')/str(pid)
 try:
  fields={k:v.strip() for k,v in (line.split(':',1) for line in (base/'status').read_text().splitlines() if ':' in line)}
  rows[str(pid)]={'state':fields['State'],'rss_kb':int(fields.get('VmRSS','0 kB').split()[0]),'threads':int(fields['Threads']),'affinity':sorted(os.sched_getaffinity(pid)),'nice':os.getpriority(os.PRIO_PROCESS,pid)}
 except FileNotFoundError:rows[str(pid)]={'state':'ABSENT'}
mem={k:int(v.split()[0]) for k,v in (line.split(':',1) for line in Path('/proc/meminfo').read_text().splitlines())}
print(json.dumps({'recorded_utc':datetime.now(timezone.utc).isoformat(),'children':rows,'mem_available_kb':mem['MemAvailable'],'scope':'Read-only host sample of the six explicitly owned child PIDs.'}))
